/* reconstructed from measured tokens */
body { font-family: "Arial", Arial, sans-serif; color: #000000; background: #FFFFFF; }
h1, h2, h3 { font-family: "Arial", Arial, sans-serif; }
a { color: #2E2E2E; }
.site-header, .main-menu { background: #3C71AC; color: #FFFFFF; }
.footer { background: #3C71AC; color: #FFFFFF; }

body {
  font-family: 'Roboto', Arial, sans-serif;
  background-color: #ffffff;
  color: #1a1a1a;
  margin: 0;
}
header.site-header {
  background-color: #ffffff;
  border-bottom: 1px solid #e0e0e0;
  padding: 12px 24px;
}
.hero-aktualne {
  position: relative;
  color: #ffffff;
}
.hero-aktualne .caption {
  background: rgba(13, 44, 84, 0.85);
  padding: 16px;
}
.news-card {
  background-color: #f5f5f5;
  border-radius: 4px;
  overflow: hidden;
}
.news-card .date {
  color: #1c4e8a;
  font-size: 12px;
}
.minister-card h3 a {
  color: #0d2c54;
  font-weight: 600;
}
.footer-patička {
  background-color: #0d2c54;
  color: #ffffff;
}

body {
  font-family: Arial, Helvetica, sans-serif;
  background-color: #ffffff;
  color: #1a1a1a;
  margin: 0;
}
.hlavni-menu {
  background-color: #003da5;
}
.hlavni-menu > ul > li > a {
  color: #ffffff;
  padding: 10px 14px;
  text-transform: uppercase;
  font-size: 12px;
}
.hlavni-menu ul ul {
  background-color: #ffffff;
  border: 1px solid #e6edf7;
  box-shadow: 0 2px 6px rgba(0,0,0,0.15);
}
.zpravodajstvi .card {
  background-color: #e6edf7;
  border-radius: 2px;
}
.zpravodajstvi .card .date {
  color: #003da5;
  font-weight: bold;
}
.rychla-linka {
  background-color: #c8102e;
  color: #ffffff;
  padding: 8px 12px;
}
footer a {
  color: #0056b3;
}
